import express, { Request, Response, NextFunction } from 'express';
import { Repository } from '../domain/models';
import { TaskService } from '../application/taskService';

export function createServer(repository: Repository): express.Application {
  const app = express();
  const taskService = new TaskService(repository);

  app.use(express.json());

  app.post('/projects', (req: Request, res: Response, next: NextFunction) => {
    try {
      const { id, name } = req.body;
      if (!id || !name) {
        res.status(400).json({ error: 'Missing id or name' });
        return;
      }
      const project = taskService.createProject(id, name);
      res.status(201).json(project);
    } catch (error) {
      next(error);
    }
  });

  app.post(
    '/users',
    (req: Request, res: Response, next: NextFunction) => {
      try {
        const { id, name } = req.body;
        if (!id || !name) {
          res.status(400).json({ error: 'Missing id or name' });
          return;
        }
        const user = taskService.createUser(id, name);
        res.status(201).json(user);
      } catch (error) {
        next(error);
      }
    }
  );

  app.post(
    '/projects/:projectId/tasks',
    (req: Request, res: Response, next: NextFunction) => {
      try {
        const projectId = req.params.projectId as string;
        const { id, title, description, dueDate } = req.body;
        if (!id || !title || !description) {
          res.status(400).json({ error: 'Missing id, title or description' });
          return;
        }
        const task = taskService.addTask(
          projectId,
          id,
          title,
          description,
          dueDate ? new Date(dueDate) : undefined
        );
        res.status(201).json(task);
      } catch (error) {
        next(error);
      }
    }
  );

  app.post(
    '/projects/:projectId/tasks/:taskId/assign',
    (req: Request, res: Response, next: NextFunction) => {
      try {
        const projectId = req.params.projectId as string;
        const taskId = req.params.taskId as string;
        const { assigneeId } = req.body;
        if (!assigneeId) {
          res.status(400).json({ error: 'Missing assigneeId' });
          return;
        }
        const task = taskService.assignTask(projectId, taskId, assigneeId);
        res.json(task);
      } catch (error) {
        next(error);
      }
    }
  );

  app.post(
    '/projects/:projectId/tasks/:taskId/done',
    (req: Request, res: Response, next: NextFunction) => {
      try {
        const projectId = req.params.projectId as string;
        const taskId = req.params.taskId as string;
        const task = taskService.markTaskDone(projectId, taskId);
        res.json(task);
      } catch (error) {
        next(error);
      }
    }
  );

  app.get(
    '/projects/:projectId/tasks',
    (req: Request, res: Response, next: NextFunction) => {
      try {
        const projectId = req.params.projectId as string;
        const status = (req.query.status as string) || undefined;
        const assigneeId = (req.query.assigneeId as string) || undefined;
        const tasks = taskService.listTasks(projectId, {
          status: status as any,
          assigneeId,
        });
        res.json(tasks);
      } catch (error) {
        next(error);
      }
    }
  );

  app.use(
    (
      error: Error,
      req: Request,
      res: Response,
      next: NextFunction
    ) => {
      res.status(400).json({ error: error.message });
    }
  );

  return app;
}

